changeSet.sql:
CREATE TABLE IF NOT EXISTS "document".payment_schedule( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, seller_company_id UUID, buyer_company_id UUID, buyer_id UUID, seller_id UUID, document_id UUID, payment_date TIMESTAMP, status TEXT, amount DOUBLE PRECISION, deleted BOOLEAN DEFAULT FALSE, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS "document".paid_schedule( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, seller_company_id UUID, buyer_company_id UUID, buyer_id UUID, seller_id UUID, document_id UUID, payment_schedule_id UUID, payment_date TIMESTAMP, status TEXT, amount DOUBLE PRECISION, deleted BOOLEAN DEFAULT FALSE, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS "document".payment_schedule_request( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, seller_company_id UUID, buyer_company_id UUID, user_id UUID, document_id UUID, payment_date TIMESTAMP, status TEXT, amount DOUBLE PRECISION, deleted BOOLEAN DEFAULT FALSE, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
ALTER TABLE document.document DROP COLUMN IF EXISTS company_id;
ALTER TABLE document.document ADD COLUMN IF NOT EXISTS buyer_company_id UUID;
ALTER TABLE document.document ADD COLUMN IF NOT EXISTS seller_company_id UUID;
ALTER TABLE document.document ADD COLUMN IF NOT EXISTS buyer_user_id UUID;
ALTER TABLE document.document ADD COLUMN IF NOT EXISTS seller_user_id UUID;
ALTER TABLE document.template ADD COLUMN IF NOT EXISTS template_type TEXT;
